static int load_moe(Model *m, int l, Layer *L) {
    const ModelConfig *c = &m->cfg; MoeWeights *w = &L->moe;
    const char *f = P ".%d.mlp.%s";
    char name[320];
    const char *ex[3] = { "switch_mlp.gate_proj", "switch_mlp.up_proj", "switch_mlp.down_proj" };
